#pragma once
#include <QImageReader>
#include <QPainter>
#include <QWidget>
#include "commerce_colors.hpp"
namespace perekup {
inline QImage nativeCommercePhoto(const QString& root,const Json& car,const Json& visuals,const std::string& colorId){QString path;QRect region;Json art=nullptr;auto model=car.value("visualModel","");if(visuals.contains(model)){art=visuals.at(model);path=QString::fromStdString(art.value("src",""));auto r=art.at("region");region=QRect(r[0].get<int>(),r[1].get<int>(),r[2].get<int>(),r[3].get<int>());}else if(car.contains("illustration")){const auto& v=car.at("illustration");path=QString::fromStdString(v.value("src",""));auto r=v.at("region");region=QRect(r[0].get<int>(),r[1].get<int>(),r[2].get<int>(),r[3].get<int>());}else path=QString::fromStdString(car.value("img",""));auto filename=root+"/assets/"+path;auto key=filename+":"+QString::number(region.x())+":"+QString::number(region.y())+":"+QString::number(region.width())+":"+QString::number(region.height())+":"+QString::fromStdString(colorId);static std::map<QString,QImage> sheets,thumbs;if(thumbs.count(key))return thumbs[key];if(!sheets.count(filename)){if(sheets.size()>=8)sheets.erase(sheets.begin());QImageReader reader(filename);sheets[filename]=reader.read();}auto image=sheets[filename];if(image.isNull()||(region.isValid()&&!image.rect().contains(region))){QStringList alternatives={QString::fromStdString(car.value("img","")),QString::fromStdString(car.value("photo","")),QString("img/commerce/")+QString::fromStdString(model)+".webp"};for(const auto& alternative:alternatives){if(alternative.isEmpty())continue;QImageReader fallback(root+"/assets/"+alternative);image=fallback.read();if(!image.isNull()){region=QRect();art=nullptr;break;}}}if(image.isNull())return {};if(region.isValid())image=image.copy(region);image=image.scaled(512,360,Qt::KeepAspectRatio,Qt::SmoothTransformation).convertToFormat(QImage::Format_ARGB32);auto color=nativeFactoryColorInfo(colorId);
 if(art.is_object()&&color&&colorId!="silver"){QImage mask(image.size(),QImage::Format_ARGB32);mask.fill(Qt::black);QPainter p(&mask);p.setRenderHint(QPainter::Antialiasing);p.scale(image.width()/1000.,image.width()/1000.);p.setPen(Qt::NoPen);auto polygons=[&](const char* field,Qt::GlobalColor fill){p.setBrush(fill);if(!art.contains(field))return;for(const auto& points:art.at(field)){QPolygonF polygon;for(const auto& point:points)polygon<<QPointF(point[0].get<double>(),point[1].get<double>());p.drawPolygon(polygon);}};polygons("body",Qt::white);polygons("glass",Qt::black);polygons("exclude",Qt::black);p.end();for(int y=0;y<image.height();++y){auto line=reinterpret_cast<QRgb*>(image.scanLine(y));auto m=reinterpret_cast<const QRgb*>(mask.constScanLine(y));for(int x=0;x<image.width();++x){double a=qRed(m[x])/255.;if(!a)continue;auto old=line[x];double lum=.2126*qRed(old)+.7152*qGreen(old)+.0722*qBlue(old);auto channel=[&](int value,double factor){return int(std::round(value*(1-a)+std::clamp(lum*factor+255*color->offset,0.,255.)*a));};line[x]=qRgba(channel(qRed(old),color->r),channel(qGreen(old),color->g),channel(qBlue(old),color->b),qAlpha(old));}}}if(thumbs.size()>=96)thumbs.erase(thumbs.begin());thumbs[key]=image;return image;
}
class CommercePhotoView:public QWidget {QImage image_;public:explicit CommercePhotoView(QImage image):image_(std::move(image)){setFixedHeight(180);setMinimumWidth(180);}void setImage(QImage image){image_=std::move(image);update();}QSize decodedSize()const{return image_.size();}protected:void paintEvent(QPaintEvent*)override{QPainter p(this);p.fillRect(rect(),QColor("#e8edeb"));if(image_.isNull()){p.drawText(rect(),Qt::AlignCenter,QStringLiteral("Фото недоступно"));return;}p.setRenderHint(QPainter::SmoothPixmapTransform);auto size=image_.size();size.scale(this->size(),Qt::KeepAspectRatio);p.drawImage(QRect((width()-size.width())/2,(height()-size.height())/2,size.width(),size.height()),image_);}};
}
